// === Tab: mySketch ===
const carTypes="💃-👯‍♂️-🚀-🪂-🚁-💺-🛷-👩‍🦽-👨‍🦽-🦼-🚗-🚘-🚙-🚕-🚖-🚓-🚔-🚒-🚑-🚌-🚍-🚎-🚐-🚚-🚛-🚜-🛺-⛽-🚨-🚧-🏎-🚂-🚃-🚆-🚉-🚝-🚋-🚲-🛴-🛵".split("-").map(a=>`${a}`)
const num=100 // Crossing number
let streets=[]
let cars

class Cars{
  constructor(){
    this.cars=carTypes.map(item=>[...random(streets),1,0,item])
  }  
  update(){
    this.cars.map(([start,end,progress,step,item],index,array)=>{
      progress+=step
      if(progress>=1){
        progress=1

        let next=[]
        for(const [A,B] of streets)
          end==A?next.push([A,B]):end==B&&next.push([B,A])

        let newStart,newEnd
        do
          [newStart,newEnd]=random(next)
        while(next.length>1&&newEnd==start)

        start=newStart
				end=newEnd
				step=sqrt((start.x-end.x)**2+(start.y-end.y)**2)/5e3
        progress=0
      }
      array[index]=[start,end,progress,step,item]
    })    
  }
  show(){
    for(const [start,end,progress,step,item] of this.cars){
      const {x,y}=p5.Vector.lerp(start,end,progress)
      text(item,x,y)    
    }
  }
}

setup=()=> {
  createCanvas(1280, 720)
  textSize(30)
  textAlign(CENTER,BOTTOM)

  let crossings=[]
  for(let i=num;i--;){
    let vector
    do
      vector=createVector(random(width), random(height))
		while(crossings.some(v=>p5.Vector.dist(v,vector)<75))
    crossings.push(vector)
  }

  streets=[]
  crossings.forEach((A,i)=>{
    crossings.filter((_,j)=>j<i).forEach(B=>{      
      const distance=(A.x-B.x)**2+(A.y-B.y)**2
      crossings.some(C=>
        distance>(A.x-C.x)**2+(A.y-C.y)**2 && distance>(B.x-C.x)**2+(B.y-C.y)**2             
      )||streets.push([A,B])
    })
  })

  cars=new Cars()
}

draw=()=> {
  background("white")

  cars.update()

  for(const lineWeight of [18,12,2]){
    push()
		strokeWeight(lineWeight)
		lineWeight==18?
			stroke('black')
    :lineWeight==12?
    	stroke('white')
    :stroke('black')+drawingContext.setLineDash([12])

    for(const [start,end] of streets)
      line(start.x,start.y,end.x,end.y)  

    cars.show()
    pop()
  }
}

keyPressed=()=>keyCode==32?setup():false
